"""
deploy_telegram_otp.py — Applique la fonctionnalité de connexion par code
Telegram (remplace le mot de passe pour les comptes liés), par-dessus la
liaison à jetons de session et le journal d'accès déjà présents dans ce
patch. À lancer depuis la racine du dépôt.
"""

import base64
import os

RACINE = os.path.dirname(os.path.abspath(__file__))

FICHIERS = {
    "api.py": """""",
    "auth.py": """""",
    "models.py": """""",
    "notifications.py": """""",
    "site/admin.html": """""",
    "site/client_upload.html": """""",
    "site/worker_dashboard.html": """""",
    "tests/test_api.py": """""",
}

for chemin_relatif, b64 in FICHIERS.items():
    chemin_complet = os.path.join(RACINE, chemin_relatif)
    os.makedirs(os.path.dirname(chemin_complet), exist_ok=True)
    with open(chemin_complet, 'wb') as f:
        f.write(base64.b64decode(b64))
    print(f'écrit : {chemin_relatif}')

print()
print('Terminé. Lance maintenant : pytest -q')